{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Isradipine, a lipophilic, poorly water-soluble dihydropyridine, has a mean systemic availability of 16.5% in healthy volunteers after oral administration, providing affirmative low-bioavailability evidence in a lipophilic small-molecule context.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Isradipine systemic availability was 16.5% in volunteers, reinforcing that lipophilic compounds with poor aqueous solubility and first-pass metabolism can fall below the 20% oral bioavailability threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Pentazocine absolute oral bioavailability was 18% in healthy subjects, providing additional low-F evidence, though its basic opioid structure is less transferable to the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is ubiquinone-9, a very large, highly lipophilic polyprenyl benzoquinone with solubility-limited absorption. No direct record exists; the most transferable low-F evidence comes from lipophilic, poorly water-soluble drugs such as isradipine (16-19%), and the query's extreme lipophilicity and high molecular weight make F >= 20% unlikely. High-F records are from structurally unrelated small molecules and do not transfer.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for ubiquinone-9 or a closely related polyprenyl quinone is provided.",
    "No formulation-specific or food-effect data for the query are available; absorption of such lipophilic quinones is highly formulation-dependent.",
    "The transferable low-F evidence is from smaller lipophilic drugs with different absorption/metabolism mechanisms, limiting confidence."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "low",
      "card_ids": ["C35"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "isradipine dihydropyridine"
    },
    {
      "applicability": "low",
      "card_ids": ["C08"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "isradipine dihydropyridine"
    },
    {
